CREATE TABLE inventory_matching_pair_pages (
 tenant TEXT NOT NULL, page_id TEXT NOT NULL, generation_id TEXT NOT NULL, destination TEXT NOT NULL, source_scope TEXT NOT NULL,
 source_config_version INTEGER NOT NULL, destination_config_version INTEGER NOT NULL, source_set_version INTEGER NOT NULL,
 work_version INTEGER NOT NULL, completed_version INTEGER NOT NULL, previous_key TEXT NOT NULL, next_key TEXT NOT NULL,
 previous_turn INTEGER NOT NULL CHECK(previous_turn>=0), next_turn INTEGER NOT NULL CHECK(next_turn>previous_turn),
 page_limit INTEGER NOT NULL CHECK(page_limit BETWEEN 1 AND 200), row_count INTEGER NOT NULL CHECK(row_count BETWEEN 0 AND page_limit), complete INTEGER NOT NULL CHECK(complete IN(0,1)),
 lease_token TEXT NOT NULL, lease_fence INTEGER NOT NULL, input_digest TEXT NOT NULL, prepared_at INTEGER NOT NULL,
 state TEXT NOT NULL DEFAULT 'prepared' CHECK(state IN('prepared','committed')), PRIMARY KEY(tenant,page_id),
 FOREIGN KEY(tenant,generation_id,destination,source_scope) REFERENCES inventory_matching_pair_jobs(tenant,generation_id,destination,source_scope),
 CHECK((row_count=0 AND complete=1 AND next_key=previous_key) OR (row_count>0 AND next_key>previous_key))
);
CREATE TABLE inventory_matching_pair_rows (
 tenant TEXT NOT NULL, page_id TEXT NOT NULL, record_key TEXT NOT NULL, expected_work_version INTEGER NOT NULL CHECK(expected_work_version>=0),
 expected_completed_version INTEGER NOT NULL CHECK(expected_completed_version>=0 AND expected_completed_version<=expected_work_version),
 PRIMARY KEY(tenant,page_id,record_key), FOREIGN KEY(tenant,page_id) REFERENCES inventory_matching_pair_pages(tenant,page_id)
);
-- Job progress locates only the page currently being published, never the
-- tenant's retained committed receipts.
CREATE INDEX inventory_matching_pair_prepared ON inventory_matching_pair_pages(tenant,generation_id,destination,source_scope,work_version,previous_key) WHERE state='prepared';
CREATE TABLE inventory_matching_pair_guards (
 tenant TEXT NOT NULL, page_id TEXT NOT NULL, PRIMARY KEY(tenant,page_id), FOREIGN KEY(tenant,page_id) REFERENCES inventory_matching_pair_pages(tenant,page_id)
);
CREATE VIEW inventory_matching_ready_pairs AS
 SELECT r.* FROM inventory_matching_source_routes r JOIN comparison_domains d ON d.tenant=r.tenant AND d.active_generation=r.generation_id
 JOIN inventory_comparison_ready_builds s ON s.tenant=r.tenant AND s.generation_id=r.generation_id AND s.scope_id=r.source_scope AND s.config_version=r.source_config_version
 JOIN inventory_comparison_ready_builds t ON t.tenant=r.tenant AND t.generation_id=r.generation_id AND t.scope_id=r.destination AND t.config_version=r.destination_config_version;
CREATE VIEW inventory_matching_pair_source_candidates AS
 SELECT h.tenant,h.page_id,i.record_key FROM inventory_matching_pair_pages h CROSS JOIN comparison_index i INDEXED BY inventory_matching_source_census
 WHERE i.tenant=h.tenant AND i.generation_id=h.generation_id AND i.scope_id=h.source_scope AND i.config_version=h.source_config_version AND i.facet='source' AND i.state!='retired' AND i.record_key>h.previous_key AND i.record_key<=h.next_key;
CREATE VIEW inventory_matching_pair_result_candidates AS
 SELECT h.tenant,h.page_id,r.record_key FROM inventory_matching_pair_pages h CROSS JOIN match_results r
 WHERE r.tenant=h.tenant AND r.destination=h.destination AND r.source_scope=h.source_scope AND r.record_key>h.previous_key AND r.record_key<=h.next_key
 AND NOT EXISTS(SELECT 1 FROM comparison_index i INDEXED BY inventory_matching_source_census WHERE i.tenant=h.tenant AND i.generation_id=h.generation_id AND i.scope_id=h.source_scope AND i.config_version=h.source_config_version AND i.facet='source' AND i.state!='retired' AND i.record_key=r.record_key);
CREATE VIEW inventory_matching_pair_stale_authority AS
 SELECT p.tenant,p.page_id FROM inventory_matching_pair_pages p WHERE NOT EXISTS(
 SELECT 1 FROM inventory_matching_pair_jobs j JOIN comparison_domains d ON d.tenant=j.tenant AND d.source_set_version=j.source_set_version
 JOIN inventory_matching_ready_pairs r ON r.tenant=j.tenant AND r.generation_id=j.generation_id AND r.destination=j.destination AND r.source_scope=j.source_scope AND r.source_config_version=j.source_config_version AND r.destination_config_version=j.destination_config_version
 JOIN leases l ON l.tenant=j.tenant AND l.scope=json_array('matching-pair',j.generation_id,j.destination,j.source_scope) AND l.token=p.lease_token AND l.fence=p.lease_fence AND l.expires_at>unixepoch('subsec')*1000
 WHERE j.tenant=p.tenant AND j.generation_id=p.generation_id AND j.destination=p.destination AND j.source_scope=p.source_scope AND j.source_config_version=p.source_config_version AND j.destination_config_version=p.destination_config_version AND j.source_set_version=p.source_set_version AND j.work_version=p.work_version AND p.prepared_at>0 AND p.prepared_at<=unixepoch('subsec')*1000);
CREATE VIEW inventory_matching_pair_invalid_census AS
 SELECT p.tenant,p.page_id FROM inventory_matching_pair_pages p WHERE p.row_count!=(SELECT count(*) FROM inventory_matching_pair_source_candidates c WHERE c.tenant=p.tenant AND c.page_id=p.page_id)+(SELECT count(*) FROM inventory_matching_pair_result_candidates c WHERE c.tenant=p.tenant AND c.page_id=p.page_id)
 OR (p.row_count>0 AND NOT EXISTS(SELECT 1 FROM inventory_matching_pair_source_candidates c WHERE c.tenant=p.tenant AND c.page_id=p.page_id AND c.record_key=p.next_key) AND NOT EXISTS(SELECT 1 FROM inventory_matching_pair_result_candidates c WHERE c.tenant=p.tenant AND c.page_id=p.page_id AND c.record_key=p.next_key))
 OR (p.complete=1 AND (
 EXISTS(SELECT 1 FROM comparison_index i INDEXED BY inventory_matching_source_census WHERE i.tenant=p.tenant AND i.generation_id=p.generation_id AND i.scope_id=p.source_scope AND i.config_version=p.source_config_version AND i.facet='source' AND i.state!='retired' AND i.record_key>p.next_key)
 OR EXISTS(SELECT 1 FROM match_results r WHERE r.tenant=p.tenant AND r.destination=p.destination AND r.source_scope=p.source_scope AND r.record_key>p.next_key)));
CREATE TRIGGER inventory_matching_pair_page_admit AFTER INSERT ON inventory_matching_pair_pages BEGIN
 SELECT CASE WHEN NEW.state!='prepared' OR NEW.next_turn!=1+(SELECT coalesce(max(last_turn),0) FROM inventory_matching_pair_jobs WHERE tenant=NEW.tenant) OR EXISTS(SELECT 1 FROM inventory_matching_pair_stale_authority WHERE tenant=NEW.tenant AND page_id=NEW.page_id) OR NOT EXISTS(SELECT 1 FROM inventory_matching_pair_jobs j WHERE j.tenant=NEW.tenant AND j.generation_id=NEW.generation_id AND j.destination=NEW.destination AND j.source_scope=NEW.source_scope AND j.work_version=NEW.work_version AND j.completed_version=NEW.completed_version AND j.completed_version<j.work_version AND j.cursor_key=NEW.previous_key AND j.last_turn=NEW.previous_turn) THEN RAISE(ABORT,'inventory matching pair authority changed') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM inventory_matching_pair_invalid_census WHERE tenant=NEW.tenant AND page_id=NEW.page_id) THEN RAISE(ABORT,'inventory matching pair range incomplete') END;
END;
CREATE TRIGGER inventory_matching_pair_guard BEFORE INSERT ON inventory_matching_pair_guards BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM inventory_matching_pair_pages p WHERE p.tenant=NEW.tenant AND p.page_id=NEW.page_id AND p.state='prepared' AND p.row_count=(SELECT count(*) FROM inventory_matching_pair_rows WHERE tenant=p.tenant AND page_id=p.page_id)) OR EXISTS(SELECT 1 FROM inventory_matching_pair_stale_authority WHERE tenant=NEW.tenant AND page_id=NEW.page_id) OR EXISTS(SELECT 1 FROM inventory_matching_pair_invalid_census WHERE tenant=NEW.tenant AND page_id=NEW.page_id) THEN RAISE(ABORT,'inventory matching pair manifest incomplete') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM inventory_matching_pair_rows q WHERE q.tenant=NEW.tenant AND q.page_id=NEW.page_id AND NOT EXISTS(SELECT 1 FROM inventory_matching_pair_source_candidates c WHERE c.tenant=q.tenant AND c.page_id=q.page_id AND c.record_key=q.record_key) AND NOT EXISTS(SELECT 1 FROM inventory_matching_pair_result_candidates c WHERE c.tenant=q.tenant AND c.page_id=q.page_id AND c.record_key=q.record_key)) THEN RAISE(ABORT,'inventory matching pair member changed') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM inventory_matching_pair_rows q JOIN inventory_matching_pair_pages p ON p.tenant=q.tenant AND p.page_id=q.page_id LEFT JOIN matching_work w ON w.tenant=q.tenant AND w.generation_id=p.generation_id AND w.destination=p.destination AND w.source_scope=p.source_scope AND w.record_key=q.record_key WHERE q.tenant=NEW.tenant AND q.page_id=NEW.page_id AND (q.expected_work_version!=coalesce(w.work_version,0) OR q.expected_completed_version!=coalesce(w.completed_version,0))) THEN RAISE(ABORT,'inventory matching pair work changed') END;
END;
DROP TRIGGER inventory_matching_pair_job_progress;
CREATE TRIGGER inventory_matching_pair_job_progress BEFORE UPDATE ON inventory_matching_pair_jobs WHEN NEW.work_version=OLD.work_version AND (NEW.completed_version!=OLD.completed_version OR NEW.cursor_key!=OLD.cursor_key OR NEW.last_turn!=OLD.last_turn) BEGIN
 SELECT CASE WHEN NEW.last_turn!=1+(SELECT coalesce(max(last_turn),0) FROM inventory_matching_pair_jobs WHERE tenant=OLD.tenant) OR NOT EXISTS(SELECT 1 FROM inventory_matching_pair_pages p JOIN inventory_matching_pair_guards g ON g.tenant=p.tenant AND g.page_id=p.page_id WHERE p.tenant=OLD.tenant AND p.generation_id=OLD.generation_id AND p.destination=OLD.destination AND p.source_scope=OLD.source_scope AND p.work_version=OLD.work_version AND p.completed_version=OLD.completed_version AND p.previous_key=OLD.cursor_key AND p.next_key=NEW.cursor_key AND p.previous_turn=OLD.last_turn AND p.next_turn=NEW.last_turn AND NEW.completed_version=CASE p.complete WHEN 1 THEN p.work_version ELSE p.completed_version END AND p.state='prepared' AND NOT EXISTS(SELECT 1 FROM inventory_matching_pair_stale_authority x WHERE x.tenant=p.tenant AND x.page_id=p.page_id)) THEN RAISE(ABORT,'inventory matching pair page guard missing') END;
END;
CREATE TRIGGER inventory_matching_pair_page_commit BEFORE UPDATE ON inventory_matching_pair_pages BEGIN
 SELECT CASE WHEN OLD.state!='prepared' OR NEW.state!='committed' OR NOT EXISTS(SELECT 1 FROM inventory_matching_pair_guards WHERE tenant=OLD.tenant AND page_id=OLD.page_id) OR EXISTS(SELECT 1 FROM inventory_matching_pair_stale_authority WHERE tenant=OLD.tenant AND page_id=OLD.page_id) OR EXISTS(SELECT 1 FROM inventory_matching_pair_invalid_census WHERE tenant=OLD.tenant AND page_id=OLD.page_id) OR NOT EXISTS(SELECT 1 FROM inventory_matching_pair_jobs j WHERE j.tenant=OLD.tenant AND j.generation_id=OLD.generation_id AND j.destination=OLD.destination AND j.source_scope=OLD.source_scope AND j.work_version=OLD.work_version AND j.completed_version=CASE OLD.complete WHEN 1 THEN OLD.work_version ELSE OLD.completed_version END AND j.cursor_key=OLD.next_key AND j.last_turn=OLD.next_turn) THEN RAISE(ABORT,'inventory matching pair commit changed') END;
 SELECT CASE WHEN (SELECT count(*) FROM inventory_matching_pair_rows WHERE tenant=OLD.tenant AND page_id=OLD.page_id)!=OLD.row_count OR (SELECT count(*) FROM inventory_matching_pair_rows q CROSS JOIN matching_work w WHERE q.tenant=OLD.tenant AND q.page_id=OLD.page_id AND w.tenant=q.tenant AND w.generation_id=OLD.generation_id AND w.destination=OLD.destination AND w.source_scope=OLD.source_scope AND w.record_key=q.record_key AND w.source_config_version=OLD.source_config_version AND w.destination_config_version=OLD.destination_config_version AND w.work_version=q.expected_work_version+1 AND w.completed_version=q.expected_completed_version AND w.due_at=0 AND w.hold_reason IS NULL)!=OLD.row_count THEN RAISE(ABORT,'inventory matching pair publication incomplete') END;
END;
CREATE TRIGGER inventory_matching_pair_page_identity BEFORE UPDATE ON inventory_matching_pair_pages WHEN (NEW.tenant,NEW.page_id,NEW.generation_id,NEW.destination,NEW.source_scope,NEW.source_config_version,NEW.destination_config_version,NEW.source_set_version,NEW.work_version,NEW.completed_version,NEW.previous_key,NEW.next_key,NEW.page_limit,NEW.row_count,NEW.complete,NEW.lease_token,NEW.lease_fence,NEW.input_digest,NEW.prepared_at) IS NOT (OLD.tenant,OLD.page_id,OLD.generation_id,OLD.destination,OLD.source_scope,OLD.source_config_version,OLD.destination_config_version,OLD.source_set_version,OLD.work_version,OLD.completed_version,OLD.previous_key,OLD.next_key,OLD.page_limit,OLD.row_count,OLD.complete,OLD.lease_token,OLD.lease_fence,OLD.input_digest,OLD.prepared_at) BEGIN SELECT RAISE(ABORT,'immutable inventory matching pair receipt'); END;
CREATE TRIGGER inventory_matching_pair_row_insert BEFORE INSERT ON inventory_matching_pair_rows WHEN NOT EXISTS(SELECT 1 FROM inventory_matching_pair_pages h WHERE h.tenant=NEW.tenant AND h.page_id=NEW.page_id AND h.state='prepared' AND NOT EXISTS(SELECT 1 FROM inventory_matching_pair_guards g WHERE g.tenant=h.tenant AND g.page_id=h.page_id)) BEGIN SELECT RAISE(ABORT,'inventory matching pair rows closed'); END;
CREATE TRIGGER inventory_matching_pair_row_update BEFORE UPDATE ON inventory_matching_pair_rows BEGIN SELECT RAISE(ABORT,'immutable inventory matching pair row'); END;
CREATE TRIGGER inventory_matching_pair_page_turn_identity BEFORE UPDATE ON inventory_matching_pair_pages WHEN (NEW.previous_turn,NEW.next_turn) IS NOT (OLD.previous_turn,OLD.next_turn) BEGIN SELECT RAISE(ABORT,'immutable inventory matching pair turn'); END;
CREATE TRIGGER inventory_matching_pair_guard_update BEFORE UPDATE ON inventory_matching_pair_guards BEGIN SELECT RAISE(ABORT,'immutable inventory matching pair guard'); END;
CREATE TRIGGER inventory_matching_pair_guard_delete BEFORE DELETE ON inventory_matching_pair_guards WHEN NOT EXISTS(SELECT 1 FROM inventory_matching_pair_pages h WHERE h.tenant=OLD.tenant AND h.page_id=OLD.page_id AND h.state='committed' AND h.prepared_at<unixepoch('subsec')*1000-604800000) BEGIN SELECT RAISE(ABORT,'retained inventory matching pair guard'); END;
CREATE TRIGGER inventory_matching_pair_page_delete BEFORE DELETE ON inventory_matching_pair_pages WHEN OLD.state!='committed' OR OLD.prepared_at>unixepoch('subsec')*1000-604800000 BEGIN SELECT RAISE(ABORT,'retained inventory matching pair receipt'); END;
CREATE TRIGGER inventory_matching_pair_row_delete BEFORE DELETE ON inventory_matching_pair_rows WHEN NOT EXISTS(SELECT 1 FROM inventory_matching_pair_pages h WHERE h.tenant=OLD.tenant AND h.page_id=OLD.page_id AND h.state='committed' AND h.prepared_at<unixepoch('subsec')*1000-604800000) BEGIN SELECT RAISE(ABORT,'retained inventory matching pair row'); END;
